// VehicleConfigurator.tsx - 3D Vehicle Customization
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, useGLTF } from '@react-three/drei';

const VehicleModel = ({ wrap, color }: ConfigProps) => {
  const { scene } = useGLTF('/models/vw-idbuzz.glb');

  useEffect(() => {
    scene.traverse((child) => {
      if (child.isMesh && child.name.includes('body')) {
        child.material = new THREE.MeshStandardMaterial({
          map: wrap ? loadTexture(wrap) : null,
          color: color,
          metalness: 0.6,
          roughness: 0.4
        });
      }
    });
  }, [wrap, color]);

  return <primitive object={scene} />;
};

export const Configurator = () => (
  <Canvas camera={{ position: [5, 2, 5] }}>
    <ambientLight intensity={0.5} />
    <VehicleModel />
    <OrbitControls />
  </Canvas>
);

// checkout.ts - Stripe Payment Integration
import Stripe from 'stripe';
import { NextApiRequest, NextApiResponse } from 'next';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const { items, customer } = req.body;

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items: items.map((item: CartItem) => ({
      price_data: {
        currency: 'usd',
        product_data: { name: item.name },
        unit_amount: item.price * 100
      },
      quantity: item.quantity
    })),
    mode: 'payment',
    success_url: `${process.env.DOMAIN}/success`,
    cancel_url: `${process.env.DOMAIN}/cart`
  });

  res.json({ sessionId: session.id });
}

